native_bridge_c:
#include <math.h>
extern int aa56_emb(double, double *);
extern double aa56_epsilon_j2000(void);
extern double swi_epsiln(double, int);
int fatebridge_aa96_native_emb(double tt, double *out) {
    double p[3], x, y, z, a, b, e;
    int code = aa56_emb(tt, p);
    if (code != 0) return code;
    x = p[2] * cos(p[1]) * cos(p[0]);
    y = p[2] * cos(p[1]) * sin(p[0]);
    z = p[2] * sin(p[1]);
    e = aa56_epsilon_j2000();
    a = cos(e) * y - sin(e) * z;
    b = sin(e) * y + cos(e) * z;
    e = swi_epsiln(2451545.0, 0);
    y = cos(e) * a + sin(e) * b;
    z = -sin(e) * a + cos(e) * b;
    out[0] = atan2(y, x);
    out[1] = atan2(z, hypot(x, y));
    out[2] = p[2];
    return 0;
}

lunar_replacement_c:
/* Experimental AA1996/full-Moshier-Moon research only, not a stock build.
   Use the full standalone geometric lunar series and the exact queried
   epoch's obliquity. Do not depend on cached oec at another sample time. */
{
  double moon[3];
  double epsilon = swi_epsiln(tjd, 0);
  int k;
  if (swi_moshmoon2(tjd, moon) != 0) {
    for (k = 0; k < 3; k++) xemb[k] = NAN;
    return;
  }
  swi_polcart(moon, moon);
  swi_coortrf2(moon, moon, -sin(epsilon), cos(epsilon));
  swi_precess(moon, tjd, 0, J_TO_J2000);
  for (k = 0; k < 3; k++) xemb[k] -= moon[k] / (EARTH_MOON_MRAT + 1.0);
  return;
}

